# Compare degenerate </think> loops between original and edited (same problems)
import json
for split in ['gen_8']:
    orig = [json.loads(l) for l in open(f'/work/{split}_original.jsonl')]
    edit = [json.loads(l) for l in open(f'/work/{split}_edited.jsonl')]
    o_rep = sum(r['text'].count('</think>')>3 for r in orig)
    e_rep = sum(r['text'].count('</think>')>3 for r in edit)
    print(split, 'orig >3 think:', o_rep, 'edited >3 think:', e_rep)
    # paired: how many problems have edited worse?
    o_map = {(r['qid'],r['sample']):r for r in orig}
    e_map = {(r['qid'],r['sample']):r for r in edit}
    o_rep_keys = {k for k,r in o_map.items() if r['text'].count('</think>')>3}
    e_rep_keys = {k for k,r in e_map.items() if r['text'].count('</think>')>3}
    print('degenerate only in edited', len(e_rep_keys - o_rep_keys), 'only in orig', len(o_rep_keys - e_rep_keys))
